import html,re
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'site/launch';REPO='https://github.com/X-lab2017/ai-for-all';URL='https://www.x-lab.info/ai-for-all/launch/'
e=lambda s:html.escape(s,quote=True)
for en in [False,True]:
 t=lambda z,a:a if en else z; lang='en' if en else 'zh';file='en.html' if en else 'index.html';article='article-en.html' if en else 'article.html'
