 ('02',t('互动演示','Interactive presentation'),t('13 章 · 中英文','13 chapters · ZH / EN'),t('从开放协作的故事，到五层全景与共建邀请。支持主题切换、逐章浏览与自动导览。','From open collaboration to the five-layer framework and an invitation to contribute. Theme controls, chapter navigation and an automatic tour.'),'presentation',[(deck,t('打开演示','Open presentation')),('downloads/AI-for-All-Presentation.zip',t('下载网页演示','Download web presentation'))]),
 ('03',t('宣言影片','The manifesto film'),'V5 · 104.4s · 1080p',t('以音乐与几何呈现共同愿景。中文屏幕文字，纯音乐，无旁白。','A shared vision in music and geometry. Chinese on-screen text, instrumental music, no narration.'),'film',[(film,t('观看影片','Watch the film')),('../film/AI-for-All-Manifesto-V5.mp4',t('下载 MP4','Download MP4'))]),
