 for i,p in enumerate(paras[1:]):
  if any(p.startswith(h) for h in headings):body+='<h2>'+e(p)+'</h2>'
  else:
   content=e(p);content=re.sub(r'https://[^\s<]+',lambda m:f'<a href="{m[0]}">{m[0]}</a>',content);body+='<p>'+content.replace('\n','<br>')+'</p>'
  if p.endswith('生生不息。') and i<7:body+='<img class="article-framework" src="assets/framework-strip.png" alt="一心普惠、二力相生、三重飞轮、万千可能、生生不息" width="1600" height="560">'
