 page+=f'''<main id="main" class="article-shell"><nav class="back-link">{link(file+'?lang='+lang,t('返回发布资料','Back to release materials'))}</nav><span class="eyebrow">X-LAB AI · 2026-10-11</span><h1>{title}</h1>{'<p class="package-note">This is the approved Chinese article.</p>' if en else ''}<img class="article-cover" src="assets/cover-wide.png" alt="AI 普惠宣言：让 AI 用得起，更用得好" width="1800" height="760"><article class="approved-article" lang="zh-CN">{body}</article><div class="article-actions">{link('downloads/AI-for-All-Publication.docx',t('下载 Word','Download Word'),True)}{link('downloads/AI-for-All-Publication.pdf',t('下载 PDF','Download PDF'),True)}<button id="copy-article" type="button">{t('复制推文全文','Copy article text')}</button><span id="copy-status" role="status"></span></div></main>'''+footer()
